CREATE TABLE `html_teleport` (
  `npcid` int(10) NOT NULL,
  `action` varchar(45) NOT NULL,
  `note` varchar(45) DEFAULT '',
  `x` int(10) NOT NULL,
  `y` int(10) NOT NULL,
  `mapid` int(10) NOT NULL,
  `heading` int(3) NOT NULL,
  `itemid` int(10) NOT NULL DEFAULT '40308',
  `count` int(10) NOT NULL DEFAULT '0',
  `min_level` int(3) NOT NULL DEFAULT '1',
  `max_level` int(3) NOT NULL DEFAULT '99',
  `fail_html` varchar(45) DEFAULT '',
  PRIMARY KEY (`npcid`,`action`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

